String fitLabel(const char *text, int width, int font) {
  String label = text;
  if (display.textWidth(label, font) > width) {
    while (label.length() && display.textWidth(label + "...", font) > width) label.remove(label.length() - 1);
    label += "...";
  }
  return label;
}

