void writeRegister(uint8_t reg, const uint8_t *params, uint8_t count) {
  display.writecommand(reg);
  for (uint8_t i = 0; i < count; i++) display.writedata(params[i]);
}

// Programs the panel's gamma on top of the controller's init. Every register a profile touches is written
// each time, so switching profiles ends up as if the board had booted with it.
void applyGamma() {
  const GammaProfile &profile = GAMMA_PROFILES[config.gammaMode];
  display.invertDisplay(!profile.normallyBlack);
  // Display function control: the init's values, with the REV bit (0x80) telling the glass type.
  const uint8_t function[] = {0x08, static_cast<uint8_t>(profile.normallyBlack ? 0x02 : 0x82), 0x27};
  writeRegister(REG_DFUNCTR, function, sizeof(function));
  writeRegister(REG_GAMMA_POS, profile.positive, profile.length);
  writeRegister(REG_GAMMA_NEG, profile.negative, profile.length);
  const uint8_t other[] = {GAMMA_CURVE_OTHER};
  const uint8_t curve[] = {GAMMA_CURVE};
  writeRegister(REG_GAMMASET, other, sizeof(other));
  delay(GAMMA_SETTLE_MS);
  writeRegister(REG_GAMMASET, curve, sizeof(curve));
}

// Tone curves for the 5-6-5 bit color channels, rebuilt when the level changes.
uint8_t toneRed[32];
uint8_t toneGreen[64];
uint8_t toneBlue[32];
uint16_t plateColor = PLATE_BASE;  // PLATE_BASE through the tone: what the card's plates are filled with.

uint16_t toneColor(uint16_t color) {
  return (toneRed[color >> 11] << 11) | (toneGreen[(color >> 5) & 0x3F] << 5) | toneBlue[color & 0x1F];
}

void applyTone() {
  const float gamma = 1.0f + config.tone * TONE_GAMMA_STEP;
  const float gain = 1.0f - config.tone * TONE_GAIN_STEP;
  for (int i = 0; i < 64; i++) toneGreen[i] = static_cast<uint8_t>(63.0f * gain * powf(i / 63.0f, gamma) + 0.5f);
  for (int i = 0; i < 32; i++) {
    toneRed[i] = toneBlue[i] = static_cast<uint8_t>(31.0f * gain * powf(i / 31.0f, gamma) + 0.5f);
  }
  plateColor = toneColor(PLATE_BASE);
}

uint16_t frameColor(const ColorStyle &style) {
  return toneColor(style.frame);
}

// Applies the tone to decoded art pixels, which are byte-swapped like the display takes them.
void toneSwapped(uint16_t *pixels, int count) {
  if (config.tone == 0) return;
  for (int i = 0; i < count; i++) pixels[i] = __builtin_bswap16(toneColor(__builtin_bswap16(pixels[i])));
}

bool savedCatalogMatches(uint32_t id, size_t count) {
  return count >= 2 && count <= TOKEN_COUNT && CATALOG_PREFIX_IDS[count - 2] == id;
}

void tableError(const char *message) {
  tableMessage = message;
  Serial.println(message);
}

void scheduleTableSave() {
  tableSaveScheduled = true;
  tableChangedAt = millis();
}

void loadTableState() {
  match.reset(4, 40);
  if (!storageReady) {
    tableError("Table storage unavailable");
    return;
  }
  Preferences tablePrefs;
  if (!tablePrefs.begin("table", false, TOKEN_PARTITION)) {
    tableError("Cannot open table storage");
    return;
  }
  if (tablePrefs.isKey("decks")) {
    if (tablePrefs.getBytesLength("decks") == sizeof(deckBook) &&
        tablePrefs.getBytes("decks", &deckBook, sizeof(deckBook)) == sizeof(deckBook) &&
        deckBook.version == 1 && deckBook.active <= tabletop::MAX_DECKS) {
      for (auto &deck : deckBook.decks) deck.name[tabletop::DECK_NAME_LIMIT] = '\0';
      if (!savedCatalogMatches(deckBook.catalog, deckBook.catalogCount)) {
        for (auto &deck : deckBook.decks) memset(deck.tokens, 0, sizeof(deck.tokens));
        deckBook.active = 0;
        tableError("Catalog changed: refill decks");
        scheduleTableSave();
      }
      if (deckBook.active && !deckBook.decks[deckBook.active - 1].name[0]) deckBook.active = 0;
    } else {
      deckBook = tabletop::DeckBook{};
      tableError("Invalid deck save");
    }
  }
  const uint8_t resume = tablePrefs.getUChar("resume", 0);
  resumeMatch = resume == 1;
  if (resume > 1) tableError("Invalid match save setting");
  const uint8_t players = tablePrefs.getUChar("players", 4);
  const int16_t initial = tablePrefs.getShort("initial", 40);
  if (players >= 1 && players <= tabletop::MAX_PLAYERS && initial >= 1 && initial <= tabletop::LIFE_LIMIT)
    match.reset(players, initial);
  else
    tableError("Invalid match defaults");
  if (resumeMatch && tablePrefs.isKey("match")) {
    if (tablePrefs.getBytesLength("match") != sizeof(match) ||
        tablePrefs.getBytes("match", &match, sizeof(match)) != sizeof(match) || !match.valid()) {
      match = tabletop::Match{};
      match.reset(4, 40);
      tableError("Invalid match save");
    }
  }
  setupPlayers = match.players;
  setupLife = match.initialLife;
  tablePrefs.end();
}

void saveTableState() {
  tableSaveScheduled = false;
  Preferences tablePrefs;
  if (!storageReady || !tablePrefs.begin("table", false, TOKEN_PARTITION)) {
    tableError("Table was not saved");
    return;
  }
  deckBook.catalog = CATALOG_ID;
  deckBook.catalogCount = TOKEN_COUNT;
  bool saved = tablePrefs.putBytes("decks", &deckBook, sizeof(deckBook)) == sizeof(deckBook);
  saved = (tablePrefs.putUChar("players", match.players) == 1) && saved;
  saved = (tablePrefs.putShort("initial", match.initialLife) == sizeof(int16_t)) && saved;
  // Disable restoration first; an interrupted erase must never restore a stale game.
  if (!resumeMatch) {
    saved = (tablePrefs.putUChar("resume", 0) == 1) && saved;
    if (tablePrefs.isKey("match")) saved = tablePrefs.remove("match") && saved;
  } else {
    const bool matchSaved = tablePrefs.putBytes("match", &match, sizeof(match)) == sizeof(match);
    saved = matchSaved && saved;
    if (matchSaved) saved = (tablePrefs.putUChar("resume", 1) == 1) && saved;
  }
  tablePrefs.end();
  if (!saved) tableError("Table save failed; see serial");
}

void loadState() {
  const esp_err_t storageError = nvs_flash_init_partition(TOKEN_PARTITION);
  storageReady = storageError == ESP_OK;
  if (!storageReady) Serial.printf("token storage init failed: %d; changes cannot be saved\n", storageError);
  migratingStorage = true;
  if (storageReady && prefs.begin("tokens", true, TOKEN_PARTITION)) {
    if (prefs.getBytesLength("catalog") == sizeof(uint32_t)) migratingStorage = false;
    else prefs.end();
  }
  if (migratingStorage && !prefs.begin("tokens", true)) {
    if (storageReady) {
      migratingStorage = true;
      saveScheduled = true;
      lastChangeAt = millis();
    }
    return;
  }
  // Settings are kept apart from the catalog check: they stay valid when the catalog changes.
  Config saved = DEFAULT_CONFIG;
  const size_t configLength = prefs.getBytesLength("config");
  if (configLength == sizeof(saved) || configLength == CONFIG_V3_SIZE || configLength == CONFIG_V2_SIZE ||
      configLength == CONFIG_V1_SIZE) {
    prefs.getBytes("config", &saved, configLength);
    if (saved.brightness >= 1 && saved.brightness <= BRIGHTNESS_LEVELS && saved.timeout < TIMEOUT_COUNT &&
        saved.layout < LAYOUT_COUNT && saved.tone < TONE_LEVELS && saved.flipped <= 1 &&
        saved.gammaMode < GAMMA_COUNT && saved.drawArea < 2 && saved.drawOpen < DRAW_OPTION_COUNT &&
        saved.drawStore < DRAW_OPTION_COUNT) {
      config = saved;
    }
  }
  const size_t length = prefs.getBytesLength("state");
  const uint32_t savedCatalog = prefs.getUInt("catalog", 0);
  size_t savedCount = length / sizeof(TokenState);
  const bool modern = length % sizeof(TokenState) == 0 && savedCatalogMatches(savedCatalog, savedCount);
  if (!modern) savedCount = length / sizeof(LegacyState);
  const bool legacy = length % sizeof(LegacyState) == 0 && savedCatalogMatches(savedCatalog, savedCount);
  if (modern || legacy) {
    if (savedCount != TOKEN_COUNT) migratingStorage = true;
    if (modern) {
      prefs.getBytes("state", states, length);
      for (TokenState &state : states) {
        for (uint8_t &kind : state.kinds) kind = min(kind, KIND_MAX);
      }
    } else {
      // Saved before the other counter kinds: keep the counts, with none of the new counters.
      prefs.getBytes("state", states, sizeof(states));
      // Expand backwards in place, without putting the whole catalog on the small ESP32 stack.
      for (size_t i = savedCount; i > 0; i--) {
        LegacyState old;
        memcpy(&old, reinterpret_cast<const uint8_t *>(states) + (i - 1) * sizeof(old), sizeof(old));
        states[i - 1] = {old.count, old.tapped, old.counters, old.powerMod, old.toughnessMod, {}};
      }
    }
    selectedToken = prefs.getUInt("sel", 0) % savedCount;
    if (prefs.getBytesLength("cnames") == savedCount * sizeof(counterNames[0])) {
      prefs.getBytes("cnames", counterNames, sizeof(counterNames));
      for (auto &name : counterNames) name[COUNTER_NAME_LIMIT] = '\0';
    }
    if (prefs.getBytesLength("outside") == savedCount * sizeof(outsideCards[0])) {
      prefs.getBytes("outside", outsideCards, sizeof(outsideCards));
      for (uint8_t &cards : outsideCards) cards = min(cards, OUTSIDE_MAX);
    }
    if (prefs.getBytesLength("foods") == savedCount * sizeof(foodTypes[0])) {
      prefs.getBytes("foods", foodTypes, sizeof(foodTypes));
      for (uint8_t &value : foodTypes) value = min(value, static_cast<uint8_t>(1));
    }
  } else if (length) {
    Serial.println("saved token catalog is incompatible; keeping custom token and settings only");
  }
  if (prefs.getBytesLength("custom") == sizeof(custom)) {
    prefs.getBytes("custom", &custom, sizeof(custom));
    custom.name[NAME_LIMIT] = '\0';
    custom.type[TYPE_LIMIT] = '\0';
    custom.text[TEXT_LIMIT] = '\0';
    if (custom.color >= COLOR_COUNT) custom.color = static_cast<uint8_t>(Color::Colorless);
  }
  prefs.end();
  if (migratingStorage && storageReady) {
    saveScheduled = true;
    lastChangeAt = millis();
  }
}

bool writeStateBytes(const char *key, const void *data, size_t size) {
  if (prefs.putBytes(key, data, size) == size) return true;
  Serial.printf("could not save '%s' (%u bytes)\n", key, static_cast<unsigned>(size));
  return false;
}

void saveState() {
  if (!storageReady || !prefs.begin("tokens", false, TOKEN_PARTITION)) {
    Serial.println("token storage unavailable; state was not saved");
    saveScheduled = false;
    return;
  }
  bool saved = writeStateBytes("state", states, sizeof(states));
  const uint32_t selection = selectedToken;
  saved = writeStateBytes("sel", &selection, sizeof(selection)) && saved;
  saved = writeStateBytes("config", &config, sizeof(config)) && saved;
  // The names rarely change, so they are only written when they do.
  if (counterNamesChanged || migratingStorage) {
    counterNamesChanged = !writeStateBytes("cnames", counterNames, sizeof(counterNames));
    saved = !counterNamesChanged && saved;
  }
  if (outsideCardsChanged || migratingStorage) {
    outsideCardsChanged = !writeStateBytes("outside", outsideCards, sizeof(outsideCards));
    saved = !outsideCardsChanged && saved;
  }
  if (foodTypesChanged || migratingStorage) {
    foodTypesChanged = !writeStateBytes("foods", foodTypes, sizeof(foodTypes));
    saved = !foodTypesChanged && saved;
  }
  if (migratingStorage) saved = writeStateBytes("custom", &custom, sizeof(custom)) && saved;
  if (saved) saved = writeStateBytes("catalog", &CATALOG_ID, sizeof(CATALOG_ID));
  if (saved) migratingStorage = false;
  prefs.end();
  saveScheduled = false;
}

void saveCustom() {
  if (migratingStorage) saveState();
  if (!storageReady || !prefs.begin("tokens", false, TOKEN_PARTITION)) {
    Serial.println("token storage unavailable; custom token was not saved");
    return;
  }
  writeStateBytes("custom", &custom, sizeof(custom));
  prefs.end();
}

void scheduleSave() {
  saveScheduled = true;
  lastChangeAt = millis();
}

String signedText(int value) {
  if (value < 0) return String(value);
  return "+" + String(value);
}

// Word-wraps text to maxW pixels and returns the line count. Lines from firstLine on are drawn
// (up to maxLines of them) only when draw is set.
int wrapText(const char *text, int font, int x, int y, int maxW, int lineH, int maxLines, bool draw,
             int firstLine = 0) {
  int lines = 0;
  String line;
  auto flush = [&]() {
    int row = lines - firstLine;
    if (draw && row >= 0 && row < maxLines) display.drawString(line, x, y + row * lineH, font);
    lines++;
    line = "";
  };
  while (*text) {
    if (*text == '\n') {
      flush();
      text++;
      continue;
    }
    if (*text == ' ') {
      text++;
      continue;
    }
    size_t length = strcspn(text, " \n");
    String word = String(text).substring(0, length);
    String candidate = line;
    if (candidate.length()) candidate += ' ';
    candidate += word;
    if (line.length() && display.textWidth(candidate, font) > maxW) {
      flush();
      candidate = word;
    }
    line = candidate;
    text += length;
  }
  if (line.length()) flush();
  return lines;
}

// Uses the larger font when the whole text fits, otherwise falls back to the small one.
void drawRulesText(const char *text, int maxH) {
  int x = G.textX + 5;
  int y = G.textY + 3;
  int maxW = G.textW - 10;
  if (wrapText(text, 2, x, y, maxW, 16, 0, false) * 16 <= maxH) {
    wrapText(text, 2, x, y, maxW, 16, maxH / 16, true);
  } else {
    wrapText(text, 1, x, y, maxW, 10, maxH / 10, true);
  }
}

const ColorStyle &styleOf(const Token &token) {
  return COLOR_STYLES[static_cast<uint8_t>(token.color)];
}

// Draws the mana symbol of a color centered on (x, y): a disc with a ring and the color's glyph. On the
// card itself the disc goes through the tone, like the rest of the card.
void drawManaSymbol(int x, int y, int radius, uint8_t color, uint16_t ring, bool toned = false) {
  const ColorStyle &style = COLOR_STYLES[color];
  auto disc = [toned](const ColorStyle &of) { return toned ? toneColor(of.pip) : of.pip; };
  display.fillCircle(x, y, radius, disc(style));
  display.drawCircle(x, y, radius, ring);

  if (color == static_cast<uint8_t>(Color::Multicolor)) {
    for (int i = 0; i < 5; i++) {
      display.fillRect(x + WHEEL_DOTS[i][0] - 1, y + WHEEL_DOTS[i][1] - 1, 3, 3, disc(COLOR_STYLES[i]));
    }
    return;
  }

  for (int row = 0; row < GLYPH_SIZE; row++) {
    const char *line = GLYPHS[color][row];
    for (int col = 0; col < GLYPH_SIZE; col++) {
      if (line[col] != '#') continue;
      int start = col;
      while (col + 1 < GLYPH_SIZE && line[col + 1] == '#') col++;
      display.drawFastHLine(x - GLYPH_SIZE / 2 + start, y - GLYPH_SIZE / 2 + row, col - start + 1, style.pipInk);
    }
  }
}

String kindName(uint8_t kind) {
  if (kind == CUSTOM_KIND && counterNames[selectedToken][0]) return counterNames[selectedToken];
  return COUNTER_KINDS[kind].name;
}

String kindLabel(uint8_t kind) {
  if (kind != CUSTOM_KIND || !counterNames[selectedToken][0]) return COUNTER_KINDS[kind].label;
  String label = String(counterNames[selectedToken]).substring(0, 7);
  label.toUpperCase();
  return label;
}

String modeLabel() {
  return MODE_LABELS[static_cast<uint8_t>(mode)];
}

// POW and TGH only apply to creatures.
bool modeAvailable(Mode value) {
  return value <= Mode::Tapped || currentToken().hasPT;
}

// Falls back to QTY when the mode does not apply to the token on show.
void validateMode() {
  if (!modeAvailable(mode)) mode = Mode::Quantity;
}

// A creature's "gets +1/+1 for each [other] Rat you control": the bonus follows what is in play.
struct Scaling {
  bool active;
  bool other;  // "each other": the creature does not count itself.
  int8_t power;
  int8_t toughness;
  char what[24];  // A type or subtype, like "Rat" or "artifact".
};

Scaling scalingOf(const Token &token) {
  Scaling scaling = {};
  if (!token.hasPT) return scaling;
  for (const char *at = strstr(token.text, "gets "); at; at = strstr(at + 1, "gets ")) {
    int power = 0;
    int toughness = 0;
    int used = 0;
    if (sscanf(at, "gets %d/%d for each %n", &power, &toughness, &used) != 2 || !used) continue;
    const char *what = at + used;
    const bool other = strncmp(what, "other ", 6) == 0;
    if (other) what += 6;
    const char *end = strstr(what, " you control");
    if (!end || end == what || static_cast<size_t>(end - what) >= sizeof(scaling.what)) continue;
    scaling = {true, other, static_cast<int8_t>(power), static_cast<int8_t>(toughness), {}};
    memcpy(scaling.what, what, end - what);
    return scaling;
  }
  return scaling;
}

// Whole words, ignoring case: "Rat" is in "Creature - Rat" but not in "Creature - Pirate".
bool typeIncludes(const char *type, const char *what) {
  const size_t length = strlen(what);
  for (const char *at = type; *at; at++) {
    if (at > type && isalpha(static_cast<unsigned char>(at[-1]))) continue;
    size_t i = 0;
    while (i < length && at[i] &&
           tolower(static_cast<unsigned char>(at[i])) == tolower(static_cast<unsigned char>(what[i]))) {
      i++;
    }
    if (i == length && !isalpha(static_cast<unsigned char>(at[length]))) return true;
  }
  return false;
}

bool markedFood(size_t index) {
  return foodTypes[index] && typeIncludes(tokenAt(index).type, "Creature");
}

String effectiveType(size_t index) {
  String type = tokenAt(index).type;
  if (markedFood(index)) {
    if (!typeIncludes(type.c_str(), "Artifact")) type = "Artifact " + type;
    if (!typeIncludes(type.c_str(), "Food")) type += " Food";
  }
  return type;
}

bool hasType(size_t index, const char *what) {
  return typeIncludes(effectiveType(index).c_str(), what);
}

// How many times the selected token's bonus applies: the matching tokens in play plus the cards the
// player added. With none of it in play yet, it counts as if one were, to show the P/T it would enter with.
int scalingCount(const Scaling &scaling) {
  int matches = outsideCards[selectedToken];
  for (size_t i = 0; i < TOKEN_COUNT; i++) {
    if (hasType(i, scaling.what)) matches += states[i].count;
  }
  if (hasType(selectedToken, scaling.what)) {
    if (states[selectedToken].count <= 0) matches++;
    if (scaling.other) matches--;
  }
  return max(matches, 0);
}

// "Rat" -> "Rats", "artifact" -> "Artifacts".
String pluralType(const char *what) {
  char text[sizeof(Scaling::what) + 1];
  const size_t length = strlen(what);
  memcpy(text, what, length + 1);
  if (length) text[0] = static_cast<char>(toupper(static_cast<unsigned char>(text[0])));
  if (length && text[length - 1] != 's') {
    text[length] = 's';
    text[length + 1] = '\0';
  }
  return text;
}

void drawMenuIcon(TFT_eSPI &out, int x, int y, uint16_t color) {
  for (int row = -1; row <= 1; ++row)
    out.fillRoundRect(x - 7, y + row * 5 - 1, 15, 3, 1, color);
}

void drawSearchIcon(TFT_eSPI &out, int x, int y, uint16_t color) {
  out.drawCircle(x - 2, y - 2, 5, color);
  out.drawCircle(x - 2, y - 2, 4, color);
  out.drawLine(x + 2, y + 2, x + 6, y + 6, color);
  out.drawLine(x + 3, y + 2, x + 6, y + 5, color);
  out.drawLine(x + 2, y + 3, x + 5, y + 6, color);
}

// Slot 0..3: previous, menu, search, next.
int overlaySlotX(const Geometry &g, int slot) {
  const int step = OV_BUTTON_W + OV_MARGIN;
  if (slot < 2) return g.artX + OV_MARGIN + slot * step;
  return g.artX + g.artW - OV_MARGIN - OV_BUTTON_W - (3 - slot) * step;
}

// Scales the brightness of an RGB565 color to keep/256.
uint16_t dimColor(uint16_t color, uint16_t keep) {
  const uint16_t r = ((color >> 11) * keep) >> 8;
  const uint16_t g = (((color >> 5) & 0x3F) * keep) >> 8;
  const uint16_t b = ((color & 0x1F) * keep) >> 8;
  return (r << 11) | (g << 5) | b;
}

// Dims a run of art pixels in the sprite; x and y are relative to the art box. The sprite keeps its
// colors byte-swapped, in the order they are sent to the display.
void dimSpan(int x, int y, int w, uint16_t keep) {
  if (y < 0 || y >= G.artH) return;
  const int end = min(x + w, static_cast<int>(G.artW));
  uint16_t *row = static_cast<uint16_t *>(artCanvas.getPointer()) + y * G.artW;
  for (int i = max(x, 0); i < end; i++) row[i] = __builtin_bswap16(dimColor(__builtin_bswap16(row[i]), keep));
}

// Dark glass under a control: dims the art inside a rounded rectangle given in screen coordinates.
void dimRoundRect(int x, int y, int w, int h, int r, uint16_t keep) {
  for (int row = 0; row < h; row++) {
    const int fromEdge = min(row, h - 1 - row);
    int inset = 0;
    if (fromEdge < r) {
      const float dy = r - fromEdge - 0.5f;
      inset = r - static_cast<int>(sqrtf(r * r - dy * dy) + 0.5f);
    }
    dimSpan(x - G.artX + inset, y - G.artY + row, w - 2 * inset, keep);
  }
}

// Fades the art rows [from, to) from keepFrom to keepTo of their brightness.
void dimBand(int from, int to, int keepFrom, int keepTo) {
  for (int y = from; y < to; y++) dimSpan(0, y, G.artW, keepFrom + (keepTo - keepFrom) * (y - from) / (to - from));
}

#if HAS_TOKEN_ART
static_assert(sizeof(TOKEN_ART) / sizeof(TOKEN_ART[0]) == CATALOG_COUNT, "token art does not match the catalog");
#endif

JPEGDEC jpeg;

// JPEGDEC hands the picture over in blocks of whole MCUs, which can run past the art box.
int copyArtBlock(JPEGDRAW *block) {
  const int w = min(block->iWidth, G.artW - block->x);
  const int h = min(block->iHeight, G.artH - block->y);
  uint16_t *pixels = static_cast<uint16_t *>(artCanvas.getPointer());
  for (int row = 0; row < h && w > 0; row++) {
    uint16_t *target = pixels + (block->y + row) * G.artW + block->x;
    memcpy(target, block->pPixels + row * block->iWidth, w * 2);
    toneSwapped(target, w);
  }
  return 1;
}

// For the thumbnails, which go straight to the display; its viewport clips the blocks.
int thumbShiftX = 0, thumbShiftY = 0;

int pushArtBlock(JPEGDRAW *block) {
  toneSwapped(block->pPixels, block->iWidth * block->iHeight);
  display.pushImage(block->x + thumbShiftX, block->y + thumbShiftY, block->iWidth, block->iHeight, block->pPixels);
  return 1;
}

// Art on a microSD card, in /mtgart, takes the place of the firmware's: it has room for the best
// quality at both sizes. tools/fetch_tokens.py writes it.
enum class SdArt : uint8_t { NoCard, Missing, Stale, Ready };
SdArt sdArt = SdArt::NoCard;
char *sdArtistText = nullptr;
const char *sdArtists[CATALOG_COUNT] = {};

void useSdPins(bool sd) {
  touchSpi.end();
  if (sd) {
    touchSpi.begin(SD_SCLK_PIN, SD_MISO_PIN, SD_MOSI_PIN, SD_CS_PIN);
  } else {
    touchSpi.begin(TOUCH_SCLK_PIN, TOUCH_MISO_PIN, TOUCH_MOSI_PIN, TOUCH_CS_PIN);
  }
}

// Reads a whole file from the card into a new, zero-terminated buffer for free(); nullptr if it is missing.
uint8_t *readSdFile(const char *path, size_t &size) {
  useSdPins(true);
  uint8_t *data = nullptr;
  File file = SD.open(path, FILE_READ);
  if (file) {
    size = file.size();
    data = static_cast<uint8_t *>(malloc(size + 1));
    if (data && file.read(data, size) != size) {
      free(data);
      data = nullptr;
    }
    if (data) data[size] = 0;
    file.close();
  }
  useSdPins(false);
  return data;
}

// Mounts the card and checks its art was made for this catalog: art files are named by catalog position.
void initSdArt() {
  sdArt = SdArt::NoCard;
  free(sdArtistText);
  sdArtistText = nullptr;
  for (const char *&artist : sdArtists) artist = nullptr;
  useSdPins(true);
  const bool mounted = SD.begin(SD_CS_PIN, touchSpi, SD_FREQUENCY);
  useSdPins(false);
  if (!mounted) {
    Serial.println("SD art: no card");
    return;
  }
  sdArt = SdArt::Missing;
  char path[40];
  size_t size = 0;
  snprintf(path, sizeof(path), "%s/catalog.txt", SD_ART_DIR);
  uint8_t *id = readSdFile(path, size);
  if (!id) {
    Serial.printf("SD art: no %s\n", path);
    return;
  }
  const uint32_t catalog = strtoul(reinterpret_cast<char *>(id), nullptr, 16);
  free(id);
  if (catalog != CATALOG_ID) {
    sdArt = SdArt::Stale;
    Serial.printf("SD art: made for catalog %08X, not %08X; rerun tools/fetch_tokens.py\n",
                  static_cast<unsigned>(catalog), static_cast<unsigned>(CATALOG_ID));
    return;
  }
  sdArt = SdArt::Ready;
  snprintf(path, sizeof(path), "%s/artists.txt", SD_ART_DIR);
  sdArtistText = reinterpret_cast<char *>(readSdFile(path, size));
  char *line = sdArtistText;
  for (size_t i = 0; line && i < CATALOG_COUNT; i++) {
    sdArtists[i] = line;
    line = strchr(line, '\n');
    if (line) *line++ = 0;
    char *end = const_cast<char *>(sdArtists[i]) + strlen(sdArtists[i]);
    if (end > sdArtists[i] && end[-1] == '\r') end[-1] = 0;
  }
  Serial.println("SD art: using the card's art");
}

const char *sdArtLabel() {
  switch (sdArt) {
    case SdArt::Missing: return "SD: NO ART";
    case SdArt::Stale: return "SD: OLD ART";
    case SdArt::Ready: return "SD HD ART";
    default: return nullptr;
  }
}

bool sdMounted() { return sdArt != SdArt::NoCard; }

// The last art file read from the card, kept so redrawing the card does not read it again.
struct SdArtCache {
  size_t token = 0;
  bool classic = false;
  uint8_t *data = nullptr;
  size_t size = 0;
} sdCache;

// Opens the card's art for the token in one size; false when there is none.
bool openSdArt(JPEG_DRAW_CALLBACK *draw, bool classic) {
  if (sdArt != SdArt::Ready) return false;
  if (!sdCache.data || sdCache.token != selectedToken || sdCache.classic != classic) {
    free(sdCache.data);
    char path[40];
    snprintf(path, sizeof(path), "%s/%s/%04u.jpg", SD_ART_DIR, classic ? "classic" : "full",
             static_cast<unsigned>(selectedToken));
    sdCache.data = readSdFile(path, sdCache.size);
    sdCache.token = selectedToken;
    sdCache.classic = classic;
  }
  return sdCache.data && jpeg.openRAM(sdCache.data, static_cast<int>(sdCache.size), draw);
}

// Opens the token's art at the full layout's size, or with classic set only the card's classic size;
// false when the token has none.
bool openArt(JPEG_DRAW_CALLBACK *draw, bool classic = false) {
  if (selectedToken == CUSTOM_INDEX) return false;
  bool opened = openSdArt(draw, classic);
#if HAS_TOKEN_ART
  if (!opened && !classic) {
    const TokenArt &art = TOKEN_ART[selectedToken - 1];
    opened = art.size != 0 && jpeg.openFLASH(const_cast<uint8_t *>(ART_DATA + art.offset), art.size, draw);
  }
#endif
  if (!opened) return false;
  // Big-endian RGB565 is the byte order the sprite stores and the display takes.
  jpeg.setPixelType(RGB565_BIG_ENDIAN);
  return true;
}

// The classic layout decodes the full layout's art here and scales it down: JPEGDEC itself only
// scales by powers of two.
uint16_t *artSource = nullptr;

int copySourceBlock(JPEGDRAW *block) {
  const int w = min(block->iWidth, FULL_ART_W - block->x);
  const int h = min(block->iHeight, FULL_ART_H - block->y);
  for (int row = 0; row < h && w > 0; row++) {
    memcpy(artSource + (block->y + row) * FULL_ART_W + block->x, block->pPixels + row * block->iWidth, w * 2);
  }
  return 1;
}

// Bilinear mix of four byte-swapped RGB565 pixels; fx and fy weigh the right and bottom ones (0-256).
uint16_t mixSwapped(uint16_t a, uint16_t b, uint16_t c, uint16_t d, int fx, int fy) {
  const uint32_t pixels[4] = {__builtin_bswap16(a), __builtin_bswap16(b), __builtin_bswap16(c), __builtin_bswap16(d)};
  const uint32_t weights[4] = {static_cast<uint32_t>((256 - fx) * (256 - fy)), static_cast<uint32_t>(fx * (256 - fy)),
                               static_cast<uint32_t>((256 - fx) * fy), static_cast<uint32_t>(fx * fy)};
  uint16_t mixed = 0;
  constexpr int SHIFTS[3] = {11, 5, 0};
  constexpr uint32_t MASKS[3] = {31, 63, 31};
  for (int channel = 0; channel < 3; channel++) {
    uint32_t sum = 32768;
    for (int i = 0; i < 4; i++) sum += ((pixels[i] >> SHIFTS[channel]) & MASKS[channel]) * weights[i];
    mixed |= (sum >> 16) << SHIFTS[channel];
  }
  return __builtin_bswap16(mixed);
}

// Scales artSource into the classic art box with one factor for both axes, trimming the rows that
// the slightly flatter box leaves over at the top and bottom.
void scaleArtSource() {
  constexpr int32_t STEP = (FULL_ART_W << 16) / CLASSIC_ART_W;
  constexpr int32_t TOP = ((FULL_ART_H << 16) - CLASSIC_ART_H * STEP) / 2;
  uint16_t *out = static_cast<uint16_t *>(artCanvas.getPointer());
  for (int y = 0; y < CLASSIC_ART_H; y++) {
    const int32_t sy = TOP + y * STEP + STEP / 2 - 0x8000;
    const int y0 = constrain(sy >> 16, 0, FULL_ART_H - 2);
    const int fy = constrain((sy - (y0 << 16)) >> 8, 0, 256);
    for (int x = 0; x < CLASSIC_ART_W; x++) {
      const int32_t sx = x * STEP + STEP / 2 - 0x8000;
      const int x0 = constrain(sx >> 16, 0, FULL_ART_W - 2);
      const int fx = constrain((sx - (x0 << 16)) >> 8, 0, 256);
      const uint16_t *p = artSource + y0 * FULL_ART_W + x0;
      *out++ = mixSwapped(p[0], p[1], p[FULL_ART_W], p[FULL_ART_W + 1], fx, fy);
    }
  }
}

// Decodes the token's art into the sprite; false when the token has none.
bool decodeArt() {
  // The card's classic-size art needs no scaling; the full-size art needs it only in the classic layout.
  if (fullBleed() ? openArt(copyArtBlock) : openArt(copyArtBlock, true)) {
    const bool decoded = jpeg.decode(0, 0, 0);
    jpeg.close();
    return decoded;
  }
  if (fullBleed()) return false;
  artSource = static_cast<uint16_t *>(malloc(FULL_ART_W * FULL_ART_H * sizeof(uint16_t)));
  if (!artSource) {
    Serial.println("no memory to scale the art");
    return false;
  }
  bool decoded = openArt(copySourceBlock);
  if (decoded) {
    decoded = jpeg.decode(0, 0, 0);
    jpeg.close();
  }
  if (decoded) {
    scaleArtSource();
    toneSwapped(static_cast<uint16_t *>(artCanvas.getPointer()), CLASSIC_ART_W * CLASSIC_ART_H);
  }
  free(artSource);
  artSource = nullptr;
  return decoded;
}

// Draws the art at a quarter (or, with half set, half) of its size, centered and cropped to the box at (x, y).
bool drawArtThumb(int x, int y, int w, int h, bool half = false) {
  if (!openArt(pushArtBlock)) return false;
  const int scale = half ? 2 : 4;
  thumbShiftX = (w - FULL_ART_W / scale) / 2;
  thumbShiftY = (h - FULL_ART_H / scale) / 2;
  display.setViewport(x, y, w, h);
  const bool decoded = jpeg.decode(0, 0, half ? JPEG_SCALE_HALF : JPEG_SCALE_QUARTER);
  display.resetViewport();
  jpeg.close();
  return decoded;
}

// Light text with a dark outline, readable on any art. Uses the current text datum.
void drawOutlined(TFT_eSPI &out, const String &text, int x, int y, int font, uint16_t color) {
  out.setTextColor(TFT_BLACK);
  for (int dy = -1; dy <= 1; dy++) {
    for (int dx = -1; dx <= 1; dx++) {
      if (dx || dy) out.drawString(text, x + dx, y + dy, font);
    }
  }
  out.setTextColor(color);
  out.drawString(text, x, y, font);
}

// Button labels too wide for font 2 fall back to the small font.
int labelFont(const String &label, int maxW) {
  return display.textWidth(label, 2) <= maxW ? 2 : 1;
}

void drawOverlayControls(TFT_eSPI &out, uint16_t artColor, bool overArt) {
  // Over the art the glass dims what is under it; on a plain color it is a darker shade of it.
  const uint16_t glass = display.alphaBlend(120, TFT_BLACK, artColor);
  auto drawGlass = [&](int x, int y, int w, int h, int r) {
    if (overArt) {
      dimRoundRect(x, y, w, h, r, GLASS_KEEP);
    } else {
      out.fillRoundRect(x, y, w, h, r, glass);
    }
    out.drawRoundRect(x, y, w, h, r, GLASS_EDGE);
  };
  const int top = G.artY + OV_MARGIN;
  const int centerY = top + OV_BUTTON_H / 2;

  for (int slot = 0; slot < 4; slot++) drawGlass(overlaySlotX(G, slot), top, OV_BUTTON_W, OV_BUTTON_H, 6);
  out.setTextDatum(MC_DATUM);
  out.setTextColor(PARCHMENT);
  out.drawString("<", overlaySlotX(G, 0) + OV_BUTTON_W / 2, centerY, 2);
  out.drawString(">", overlaySlotX(G, 3) + OV_BUTTON_W / 2, centerY, 2);
  drawMenuIcon(out, overlaySlotX(G, 1) + OV_BUTTON_W / 2, centerY, PARCHMENT);
  drawSearchIcon(out, overlaySlotX(G, 2) + OV_BUTTON_W / 2, centerY, PARCHMENT);

  for (int side = 0; side < 2; side++) {
    int x = side == 0 ? G.artX + OV_BIG_INSET : G.artX + G.artW - OV_BIG_INSET;
    drawGlass(x - OV_BIG_R, G.countY - OV_BIG_R, 2 * OV_BIG_R + 1, 2 * OV_BIG_R + 1, OV_BIG_R);
    out.fillRect(x - 8, G.countY - 1, 17, 3, PARCHMENT);
    if (side == 1) out.fillRect(x - 1, G.countY - 8, 3, 17, PARCHMENT);
  }

  const int chipX = G.artX + (G.artW - OV_CHIP_W) / 2;
  const int chipY = G.groupY - OV_CHIP_H / 2;
  drawGlass(chipX, chipY, OV_CHIP_W, OV_CHIP_H, 11);
  const String label = modeLabel();
  out.setTextColor(HIGHLIGHT);
  out.drawString(label, chipX + OV_CHIP_W / 2, G.groupY, labelFont(label, OV_CHIP_W - 8));
}

bool tapGroupsVisible() {
  return screen == Screen::Card &&
         (states[selectedToken].count > 0 ||
          (mode == Mode::Quantity && (layout() != Layout::CardOnly || countFlash)));
}

void drawTapGroup(TFT_eSPI &out, int x, int count, bool tapped) {
  bool active = (mode == Mode::Tapped && tapped) ||
                (mode == Mode::Quantity && quantityTapped == tapped);
  uint16_t color = active ? HIGHLIGHT : PARCHMENT;
  int iconW = tapped ? 16 : 11;
  int iconH = tapped ? 11 : 16;
  int y = G.groupY;
  // Dark rims keep the card outline visible on light art.
  out.drawRoundRect(x - 1, y - iconH / 2 - 1, iconW + 2, iconH + 2, 3, TFT_BLACK);
  if (active) {
    out.fillRoundRect(x, y - iconH / 2, iconW, iconH, 2, HIGHLIGHT);
  } else {
    out.drawRoundRect(x, y - iconH / 2, iconW, iconH, 2, color);
    out.drawRoundRect(x + 1, y - iconH / 2 + 1, iconW - 2, iconH - 2, 1, TFT_BLACK);
  }
  out.setTextDatum(ML_DATUM);
  drawOutlined(out, String(count), x + iconW + 5, y, 2, color);
}

void drawArt() {
  const Token token = currentToken();
  const TokenState &state = states[selectedToken];
  const uint16_t artColor = display.alphaBlend(120, frameColor(styleOf(token)), TFT_BLACK);
  const bool composed = artCanvas.created();
  TFT_eSPI &out = composed ? static_cast<TFT_eSPI &>(artCanvas) : display;
  const int centerX = G.artX + G.artW / 2;

  if (composed) {
    if (!decodeArt()) artCanvas.fillSprite(artColor);
    // Darker top and bottom edges under the labels and controls.
    const int band = fullBleed() ? 34 : 28;
    dimBand(0, band, BAND_KEEP, 256);
    dimBand(G.artH - band, G.artH, 256, BAND_KEEP);
    // From here on the sprite is drawn in screen coordinates, like the rest of the card.
    artCanvas.setViewport(-G.artX, -G.artY, G.artX + G.artW, G.artY + G.artH);
  } else {
    display.fillRect(G.artX, G.artY, G.artW, G.artH, artColor);
  }

  // A single token (or none) leaves the art clear, except briefly after the quantity changes.
  const bool editingDrawing = screen == Screen::Drawing;
  const bool showCount = !editingDrawing && (state.count > 1 || countFlash);
  out.setTextDatum(TC_DATUM);
  if (showCount) drawOutlined(out, "IN PLAY", centerX, G.artY + (fullBleed() ? 5 : 6), 2, PARCHMENT);
  if (positionVisible && !editingDrawing) {
    size_t ordinal = 0;
    for (size_t i = 0; i <= selectedToken; ++i) if (deckBook.includes(i)) ++ordinal;
    String position = String(ordinal) + "/" + String(deckBook.count(TOKEN_COUNT));
    if (fullBleed()) {
      drawOutlined(out, position, centerX, G.artY + 22, 1, PARCHMENT);
    } else {
      out.setTextDatum(TR_DATUM);
      drawOutlined(out, position, G.artX + G.artW - 5, G.artY + 5, 1, PARCHMENT);
    }
  }
  out.setTextDatum(MC_DATUM);
  if (showCount) drawOutlined(out, String(state.count), centerX, G.countY, 7, PARCHMENT);

  if (tapGroupsVisible()) {
    drawTapGroup(out, G.groupLeftX, state.count - state.tapped, false);
    drawTapGroup(out, G.groupRightX, state.tapped, true);
  }
  if (!composed) display.setViewport(G.artX, G.artY, G.artW, G.artH, false);
  drawDoodle(out);
  if (!composed) display.resetViewport();
  if (fullBleed() && controlsVisible()) drawOverlayControls(out, artColor, composed);

  if (composed) {
    artCanvas.resetViewport();
    artCanvas.pushSprite(G.artX, G.artY);
  }
}

// Counters and modifiers share one line to the left of the P/T box.
void drawStatusLine(const TokenState &state) {
  String counters;
  String mods;
  if (state.counters != 0) {
    counters = state.counters >= 0 ? "+1/+1 x" : "-1/-1 x";
    counters += abs(state.counters);
  }
  if (state.powerMod != 0 || state.toughnessMod != 0 || mode == Mode::Power || mode == Mode::Toughness) {
    mods = "Mod " + signedText(state.powerMod) + "/" + signedText(state.toughnessMod);
  }

  int font = display.textWidth(counters + "  " + mods, 2) <= G.ptX - G.textX - 6 ? 2 : 1;
  int x = G.textX + 4;
  int y = G.statusY + (font == 2 ? 1 : 5);
  display.setTextDatum(TL_DATUM);
  display.setTextColor(CARD_INK, plateColor);
  if (counters.length()) {
    display.drawString(counters, x, y, font);
    x += display.textWidth(counters, font) + (font == 2 ? 10 : 6);
  }
  if (mods.length()) display.drawString(mods, x, y, font);
}

// What the selected token's "for each" ability adds right now, like "Rats +4/+4"; empty when nothing.
String scalingBonusText() {
  const Scaling scaling = scalingOf(currentToken());
  const int times = scaling.active ? scalingCount(scaling) : 0;
  if (!times) return String();
  return pluralType(scaling.what) + " " + signedText(scaling.power * times) + "/" +
         signedText(scaling.toughness * times);
}

bool hasKindCounters() {
  for (uint8_t value : states[selectedToken].kinds) {
    if (value) return true;
  }
  return false;
}

// Top of the badge row: above the status line on creatures, at the bottom of the text box otherwise.
int badgeRowY() {
  return currentToken().hasPT ? G.statusY - BADGE_H - 2 : G.textY + G.textH - BADGE_H - 3;
}

String badgeText(uint8_t kind, bool shortForm) {
  const uint8_t value = states[selectedToken].kinds[kind];
  String text = shortForm ? kindLabel(kind) : kindName(kind);
  if (!COUNTER_KINDS[kind].keyword || value > 1) text += " " + String(value);
  return text;
}

int badgeWidth(const String &text) {
  return display.textWidth(text, 1) + 6;
}

void drawBadge(int x, int y, const String &text, uint16_t fill, uint16_t ink) {
  display.fillRoundRect(x, y, badgeWidth(text), BADGE_H, 4, fill);
  display.setTextColor(ink, fill);
  display.drawString(text, x + 3, y + BADGE_H / 2, 1);
}

// One row of pills: the "for each" bonus first, then the token's other counters, in full words when
// they all fit. Whatever does not fit even in short form is summed up in a last "+N" pill.
void drawBadges(int y) {
  const TokenState &state = states[selectedToken];
  const String bonus = scalingBonusText();
  const bool food = markedFood(selectedToken);
  const int left = G.textX + 4;
  const int right = G.textX + G.textW - 4;
  display.setTextDatum(ML_DATUM);
  int remaining = 0;
  int fullWidth = -BADGE_GAP;
  for (int kind = -2; kind < KIND_COUNT; kind++) {
    if (kind == -2 ? !bonus.length() : kind == -1 ? !food : !state.kinds[kind]) continue;
    const String text = kind == -2 ? bonus : kind == -1 ? String("Food (Ygra)") : badgeText(kind, false);
    remaining++;
    fullWidth += badgeWidth(text) + BADGE_GAP;
  }
  const bool shortForm = fullWidth > right - left;
  int x = left;
  for (int kind = -2; kind < KIND_COUNT; kind++) {
    if (kind == -2 ? !bonus.length() : kind == -1 ? !food : !state.kinds[kind]) continue;
    const String text = kind == -2 ? bonus : kind == -1 ? String("Food (Ygra)") : badgeText(kind, shortForm);
    remaining--;
    // Each badge leaves room for the "+N" pill that would follow it.
    const int reserve = remaining ? badgeWidth("+" + String(remaining)) + BADGE_GAP : 0;
    if (x + badgeWidth(text) + reserve > right) {
      drawBadge(x, y, "+" + String(remaining + 1), HINT, INK);
      return;
    }
    const uint16_t fill = kind < 0 ? BONUS_PILL : COUNTER_KINDS[kind].keyword ? KEYWORD_PILL : COUNTER_PILL;
    drawBadge(x, y, text, fill, PARCHMENT);
    x += badgeWidth(text) + BADGE_GAP;
  }
}

void drawTextBox() {
  const Token token = currentToken();
  display.fillRect(G.textX, G.textY, G.textW, G.textH, plateColor);
  display.setTextDatum(TL_DATUM);
  if (selectedToken == CUSTOM_INDEX && token.text[0] == '\0') {
    display.setTextColor(HINT, plateColor);
    display.drawString("Tap here to edit", G.textX + 5, G.textY + 3, 2);
  }
  display.setTextColor(CARD_INK, plateColor);
  const bool badges = hasKindCounters() || scalingBonusText().length() || markedFood(selectedToken);
  int rulesH = token.hasPT ? G.textH - 26 : G.textH - 6;
  if (badges) rulesH = badgeRowY() - G.textY - 5;
  drawRulesText(token.text, rulesH);
  if (badges) drawBadges(badgeRowY());
  if (token.hasPT) drawStatusLine(states[selectedToken]);
}

String statLabel(int base, const char *symbol, int modifier) {
  if (!symbol) return String(base + modifier);
  return String(symbol) + (modifier ? signedText(modifier) : String());
}

String printedPT(const Token &token) {
  return statLabel(token.power, token.powerSymbol, 0) + "/" +
         statLabel(token.toughness, token.toughnessSymbol, 0);
}

// Unknown variable stats stay symbolic rather than pretending they are zero.
String ptLabel() {
  const Token token = currentToken();
  const TokenState &state = states[selectedToken];
  int powerMod = state.counters + state.powerMod;
  int toughnessMod = state.counters + state.toughnessMod;
  const Scaling scaling = scalingOf(token);
  if (scaling.active) {
    const int times = scalingCount(scaling);
    powerMod += scaling.power * times;
    toughnessMod += scaling.toughness * times;
  }
  return statLabel(token.power, token.powerSymbol, powerMod) + "/" +
         statLabel(token.toughness, token.toughnessSymbol, toughnessMod);
}

void drawPT() {
  const Token token = currentToken();
  if (!token.hasPT) return;

  uint16_t border = (mode == Mode::Power || mode == Mode::Toughness) ? HIGHLIGHT : TFT_BLACK;
  display.fillRoundRect(G.ptX, G.ptY, PT_W, PT_H, 5, plateColor);
  display.drawRoundRect(G.ptX, G.ptY, PT_W, PT_H, 5, border);
  display.drawRoundRect(G.ptX + 1, G.ptY + 1, PT_W - 2, PT_H - 2, 4, border);

  const String label = ptLabel();
  int font = display.textWidth(label, 4) <= PT_W - 6 ? 4 : display.textWidth(label, 2) <= PT_W - 6 ? 2 : 1;
  display.setTextDatum(MC_DATUM);
  display.setTextColor(CARD_INK, plateColor);
  if (display.textWidth(label, font) <= PT_W - 6) {
    display.drawString(label, G.ptX + PT_W / 2, G.ptY + PT_H / 2 + 1, font);
  } else {
    const size_t slash = strchr(label.c_str(), '/') - label.c_str();
    display.drawString(label.substring(0, slash), G.ptX + PT_W / 2, G.ptY + 8, 1);
    display.drawString(label.substring(slash), G.ptX + PT_W / 2, G.ptY + 18, 1);
  }
}

// The P/T box overlaps the text box, so it must be drawn after it.
void drawCardValues() {
  drawArt();
  drawTextBox();
  drawPT();
  // Ink outside the art only shows when doodles may cover the whole card; it stays stored either way.
  if (drawArtOnly()) return;
  display.setViewport(G.cardX, G.cardY, G.cardW, G.artY - G.cardY, false);
  drawDoodle(display);
  display.setViewport(G.cardX, G.artY + G.artH, G.cardW, G.cardY + G.cardH - G.artY - G.artH, false);
  drawDoodle(display);
  display.setViewport(G.cardX, G.artY, G.artX - G.cardX, G.artH, false);
  drawDoodle(display);
  display.setViewport(G.artX + G.artW, G.artY, G.cardX + G.cardW - G.artX - G.artW, G.artH, false);
  drawDoodle(display);
  display.resetViewport();
}

// Long type lines (Enchantment Artifact Creature - Golem) wrap onto two lines of the small font.
void drawTypeLine(const char *type) {
  const int x = G.plateX + 6;
  const int maxW = G.plateW - 12;
  display.setTextColor(CARD_INK, plateColor);
  int font = display.textWidth(type, 2) <= maxW ? 2 : 1;
  if (display.textWidth(type, font) <= maxW) {
    display.setTextDatum(ML_DATUM);
    display.drawString(type, x, G.typeY + G.typeH / 2, font);
  } else {
    display.setTextDatum(TL_DATUM);
    wrapText(type, 1, x, G.typeY + 3, maxW, 9, 2, true);
  }
}

// The illustrator's name under the text box, where a real card prints it.
void drawArtistCredit(const ColorStyle &style) {
  if (selectedToken == CUSTOM_INDEX) return;
  const char *name = sdArtists[selectedToken - 1];
#if HAS_TOKEN_ART
  if (!name) name = TOKEN_ART[selectedToken - 1].artist;
#endif
  String artist = name ? name : "";
  if (artist.length() == 0) return;
  const int x = G.textX + 2;
  const int y = G.textY + G.textH + 1;
  const int maxW = (currentToken().hasPT ? G.ptX - 4 : G.textX + G.textW) - x - 10;
  if (display.textWidth(artist, 1) > maxW) {
    while (artist.length() > 1 && display.textWidth(artist + ".", 1) > maxW) artist.remove(artist.length() - 1);
    artist += ".";
  }
  // A little paintbrush, as on the cards.
  display.drawLine(x + 6, y, x + 3, y + 3, style.pipInk);
  display.drawLine(x + 7, y + 1, x + 4, y + 4, style.pipInk);
  display.fillRect(x + 1, y + 4, 3, 2, style.pipInk);
  display.drawPixel(x, y + 6, style.pipInk);
  display.setTextDatum(TL_DATUM);
  display.setTextColor(style.pipInk, frameColor(style));
  display.drawString(artist, x + 10, y, 1);
}

void drawCard() {
  const Token token = currentToken();
  const ColorStyle &style = styleOf(token);
  display.fillRoundRect(G.cardX, G.cardY, G.cardW, G.cardH, G.radius, TFT_BLACK);
  display.fillRoundRect(G.cardX + G.inset, G.cardY + G.inset, G.cardW - 2 * G.inset, G.cardH - 2 * G.inset,
                        G.frameRadius, frameColor(style));

  display.fillRoundRect(G.plateX, G.titleY, G.plateW, G.titleH, 4, plateColor);
  display.setTextColor(CARD_INK, plateColor);
  display.setTextDatum(ML_DATUM);
  int nameFont = display.textWidth(token.name, 2) <= G.plateW - 32 ? 2 : 1;
  display.drawString(fitLabel(token.name, G.plateW - 32, nameFont), G.plateX + 6, G.titleY + G.titleH / 2, nameFont);
  drawManaSymbol(G.plateX + G.plateW - 13, G.titleY + G.titleH / 2, 9, static_cast<uint8_t>(token.color), TFT_BLACK,
                 true);

  display.fillRoundRect(G.plateX, G.typeY, G.plateW, G.typeH, 4, plateColor);
  drawTypeLine(effectiveType(selectedToken).c_str());
  drawArtistCredit(style);

  drawCardValues();
}

void drawButton(int index, const String &label, uint16_t color) {
  int x = 1 + index * BUTTON_STEP;
  display.fillRoundRect(x, BAR_Y, BUTTON_W, BUTTON_H, 4, PANEL);
  display.drawRoundRect(x, BAR_Y, BUTTON_W, BUTTON_H, 4, 0x7BEF);
  display.setTextDatum(MC_DATUM);
  display.setTextColor(color, PANEL);
  display.drawString(label, x + BUTTON_W / 2, BAR_Y + BUTTON_H / 2, labelFont(label, BUTTON_W - 4));
}

// The full-screen layouts have no bar: their controls float over the art.
void drawControls() {
  if (fullBleed()) return;
  drawButton(0, "<", INK);
  drawButton(1, "-", INK);
  drawButton(2, modeLabel(), HIGHLIGHT);
  drawButton(3, "+", INK);
  drawButton(4, ">", INK);
}

void drawDoodlePalette() {
  display.fillRoundRect(PALETTE_X, PALETTE_Y, PALETTE_W, PALETTE_H, 6, BACKGROUND);
  display.drawRoundRect(PALETTE_X, PALETTE_Y, PALETTE_W, PALETTE_H, 6, HINT);
  for (int i = 0; i < 8; i++) {
    const int x = PALETTE_X + PALETTE_COLOR_W / 2 + i * PALETTE_COLOR_W, y = PALETTE_Y + 23;
    display.fillCircle(x, y, 10, DOODLE_COLORS[i]);
    display.drawCircle(x, y, 13, !doodleEraser && doodleColor == i ? HIGHLIGHT : HINT);
  }
  display.setTextDatum(MC_DATUM);
  const uint16_t dot = doodleEraser || DOODLE_COLORS[doodleColor] == TFT_BLACK ? INK : DOODLE_COLORS[doodleColor];
  for (int i = 0; i < 4; i++) {
    const int x = PALETTE_X + PALETTE_BRUSH_W / 2 + i * PALETTE_BRUSH_W, y = PALETTE_SPLIT_Y + 20;
    const bool selected = i == 3 ? doodleEraser : !doodleEraser && doodleBrush == i;
    display.drawRoundRect(x - 25, y - 16, 50, 32, 5, selected ? HIGHLIGHT : HINT);
    if (i < 3) {
      display.fillCircle(x, y, DOODLE_RADII[i] + 1, dot);
    } else {
      display.setTextColor(selected ? HIGHLIGHT : INK, BACKGROUND);
      display.drawString("ERASE", x, y, 1);
    }
  }
}

void drawScreen() {
  loadDoodle();
  display.fillScreen(BACKGROUND);
  drawCard();
  if (screen == Screen::Drawing) {
    drawButton(0, "BACK", INK);
    drawButton(1, doodleEraser ? "ERASE" : "PEN",
               doodleEraser || DOODLE_COLORS[doodleColor] == TFT_BLACK ? HINT : DOODLE_COLORS[doodleColor]);
    drawButton(2, "UNDO", INK);
    drawButton(3, "CLEAR", INK);
    drawButton(4, "SAVE", drawStore() == DrawStore::Ram ? HINT : HIGHLIGHT);
    if (doodlePalette) drawDoodlePalette();
    return;
  }
  drawControls();
  if (!fullBleed()) {
    // The card leaves a margin on each side for the menu and search icons.
    drawMenuIcon(display, G.cardX / 2, 16, HINT);
    drawSearchIcon(display, SCREEN_W - G.cardX / 2 - 1, 16, HINT);
  }
}

bool containsWord(const char *text, const char *word, size_t length) {
  for (; *text; text++) {
    size_t i = 0;
    while (i < length && text[i] &&
           tolower(static_cast<unsigned char>(text[i])) == tolower(static_cast<unsigned char>(word[i]))) {
      i++;
    }
    if (i == length) return true;
  }
  return false;
}

// Every word of the query must appear (in any order, ignoring case) in the name, type line, rules
// text, color name or the printed power/toughness such as "3/3".
bool matchesQuery(size_t index, const char *query) {
  const Token token = tokenAt(index);
  const String powerToughness = token.hasPT ? printedPT(token) : String();
  const String type = effectiveType(index);
  const char *fields[] = {token.name, type.c_str(), token.text, COLOR_NAMES[static_cast<uint8_t>(token.color)],
                          powerToughness.c_str()};
  while (*query) {
    if (*query == ' ') {
      query++;
      continue;
    }
    size_t length = strcspn(query, " ");
    bool found = false;
    for (const char *field : fields) {
      if (containsWord(field, query, length)) {
        found = true;
        break;
      }
    }
    if (!found) return false;
    query += length;
  }
  return true;
}

size_t countMatches(const char *query) {
  size_t count = 0;
  for (size_t i = 0; i < TOKEN_COUNT; i++) {
    if ((editingDeckTokens || deckBook.includes(i)) && matchesQuery(i, query)) count++;
  }
  return count;
}

void rebuildMatches() {
  matchCount = 0;
  for (size_t i = 0; i < TOKEN_COUNT; i++) {
    if ((editingDeckTokens || deckBook.includes(i)) && matchesQuery(i, searchQuery)) matches[matchCount++] = i;
  }
}

void clearSearch() {
  searchQuery[0] = '\0';
  rebuildMatches();
}

// Every word of the query must appear in the precon's name, set code or release year.
bool preconMatchesQuery(size_t index, const char *query) {
  const PreconDeck &precon = PRECONS[index];
  char year[6];
  snprintf(year, sizeof(year), "%u", precon.year);
  const char *fields[] = {precon.name, precon.code, year};
  while (*query) {
    if (*query == ' ') {
      query++;
      continue;
    }
    const size_t length = strcspn(query, " ");
    bool found = false;
    for (const char *field : fields) found = found || containsWord(field, query, length);
    if (!found) return false;
    query += length;
  }
  return true;
}

void rebuildPreconMatches() {
  preconMatchCount = 0;
  for (size_t i = 0; i < PRECON_COUNT; i++)
    if (preconMatchesQuery(i, preconQuery)) preconMatches[preconMatchCount++] = i;
  preconPage = 0;
}

size_t preconPageCount() {
  const size_t pages = (preconMatchCount + ROWS_PER_PAGE - 1) / ROWS_PER_PAGE;
  return pages ? pages : 1;
}

// The deck slot holding this precon (matched by its possibly shortened name), or MAX_DECKS.
uint8_t preconSlot(size_t index) {
  char name[tabletop::DECK_NAME_LIMIT + 1];
  strlcpy(name, PRECONS[index].name, sizeof(name));
  for (uint8_t slot = 0; slot < tabletop::MAX_DECKS; ++slot)
    if (!strcmp(deckBook.decks[slot].name, name)) return slot;
  return tabletop::MAX_DECKS;
}

uint8_t freeDeckSlot() {
  uint8_t slot = 0;
  while (slot < tabletop::MAX_DECKS && deckBook.decks[slot].name[0]) ++slot;
  return slot;
}

// Copies a precon's tokens into a deck slot (replacing an earlier copy of it) and activates it.
bool importPrecon(size_t index) {
  uint8_t slot = preconSlot(index);
  if (slot == tabletop::MAX_DECKS) slot = freeDeckSlot();
  if (slot == tabletop::MAX_DECKS) return false;
  const PreconDeck &precon = PRECONS[index];
  tabletop::Deck deck;
  strlcpy(deck.name, precon.name, sizeof(deck.name));
  for (uint16_t i = 0; i < precon.count; ++i) {
    const uint16_t token = PRECON_TOKENS[precon.first + i];
    if (token < TOKEN_COUNT && !deck.contains(token)) deck.toggle(token);
  }
  deckBook.decks[slot] = deck;
  deckBook.active = slot + 1;
  scheduleTableSave();
  return true;
}

size_t pageCount() {
  size_t pages = (matchCount + ROWS_PER_PAGE - 1) / ROWS_PER_PAGE;
  return pages ? pages : 1;
}

void drawPicker() {
  display.fillScreen(BACKGROUND);
  display.setTextColor(INK, BACKGROUND);
  String pages = String(pickerPage + 1) + "/" + String(pageCount());
  if (searchQuery[0]) {
    display.setTextColor(HIGHLIGHT, BACKGROUND);
    display.setTextDatum(ML_DATUM);
    display.drawString(searchQuery, 8, 12, display.textWidth(searchQuery, 2) <= 170 ? 2 : 1);
    display.setTextColor(HINT, BACKGROUND);
    display.setTextDatum(MR_DATUM);
    display.drawString(pages, SCREEN_W - 8, 12, 2);
  } else {
    display.setTextDatum(MC_DATUM);
    const String title = editingDeckTokens ? "ADD/REMOVE " : deckBook.active ? "DECK TOKENS " : "SELECT TOKEN ";
    display.drawString(title + pages, SCREEN_W / 2, 12, 2);
  }

  if (matchCount == 0) {
    display.setTextDatum(MC_DATUM);
    display.setTextColor(HINT, BACKGROUND);
    display.drawString("No token matches", SCREEN_W / 2, LIST_Y + 60, 2);
    display.drawString("Press FIND to try again", SCREEN_W / 2, LIST_Y + 84, 2);
  }

  for (int row = 0; row < ROWS_PER_PAGE; row++) {
    size_t position = pickerPage * ROWS_PER_PAGE + row;
    if (position >= matchCount) break;
    size_t index = matches[position];
    const Token token = tokenAt(index);
    int y = LIST_Y + row * ROW_H;
    int centerY = y + ROW_H / 2;
    uint16_t rowColor = index == selectedToken ? PANEL_SELECTED : PANEL;
    display.fillRoundRect(4, y + 1, SCREEN_W - 8, ROW_H - 2, 4, rowColor);

    drawManaSymbol(18, centerY, 9, static_cast<uint8_t>(token.color), HINT);

    display.setTextDatum(ML_DATUM);
    display.setTextColor(INK, rowColor);
    int nameFont = display.textWidth(token.name, 2) <= 130 ? 2 : 1;
    display.drawString(fitLabel(token.name, 130, nameFont), 32, centerY, nameFont);

    display.setTextDatum(MR_DATUM);
    if (token.hasPT && !editingDeckTokens) {
      const String pt = printedPT(token);
      display.drawString(pt, SCREEN_W - 46, centerY, display.textWidth(pt, 2) <= 40 ? 2 : 1);
    }
    if (editingDeckTokens) {
      display.setTextColor(deckBook.includes(index) ? HIGHLIGHT : HINT, rowColor);
      display.drawString(deckBook.includes(index) ? "YES" : "-", SCREEN_W - 8, centerY, 1);
    } else if (states[index].count > 0) {
      display.setTextColor(HIGHLIGHT, rowColor);
      display.drawString("x" + String(states[index].count), SCREEN_W - 10, centerY, 2);
    }
  }

  drawButton(0, "<", INK);
  drawButton(1, "FIND", searchQuery[0] ? HIGHLIGHT : INK);
  drawButton(2, "BACK", INK);
  drawButton(3, "DECKS", HIGHLIGHT);
  drawButton(4, ">", INK);
}

// A quarter-scale sketch of the card screen, drawn from the real geometry so it always matches.
void drawLayoutThumb(int x, int y, Layout which) {
  const Geometry &g = which == Layout::Classic ? CLASSIC_GEO : FULL_GEO;
  const ColorStyle &style = styleOf(currentToken());
  const uint16_t frame = frameColor(style);
  const uint16_t artColor = display.alphaBlend(120, frame, TFT_BLACK);
  auto sx = [x](int value) { return x + value / 4; };
  auto sy = [y](int value) { return y + value / 4; };

  display.fillRect(x, y, THUMB_W, THUMB_H, BACKGROUND);
  display.fillRoundRect(sx(g.cardX), sy(g.cardY), g.cardW / 4, g.cardH / 4, 3, TFT_BLACK);
  display.fillRoundRect(sx(g.cardX + g.inset), sy(g.cardY + g.inset), (g.cardW - 2 * g.inset) / 4,
                        (g.cardH - 2 * g.inset) / 4, 2, frame);
  display.fillRect(sx(g.plateX), sy(g.titleY), g.plateW / 4, g.titleH / 4, plateColor);
  if (!drawArtThumb(sx(g.artX), sy(g.artY), g.artW / 4, g.artH / 4)) {
    display.fillRect(sx(g.artX), sy(g.artY), g.artW / 4, g.artH / 4, artColor);
  }
  display.fillRect(sx(g.plateX), sy(g.typeY), g.plateW / 4, g.typeH / 4, plateColor);
  display.fillRect(sx(g.textX), sy(g.textY), g.textW / 4, g.textH / 4, plateColor);
  display.fillRect(sx(g.ptX), sy(g.ptY), PT_W / 4, PT_H / 4, plateColor);
  display.drawRect(sx(g.ptX), sy(g.ptY), PT_W / 4, PT_H / 4, TFT_BLACK);
  display.fillRect(sx(g.artX + g.artW / 2) - 2, sy(g.countY) - 4, 4, 8, PARCHMENT);

  if (which == Layout::Classic) {
    for (int i = 0; i < 5; i++) {
      display.fillRect(sx(1 + i * BUTTON_STEP), sy(BAR_Y), BUTTON_W / 4, BUTTON_H / 4, PANEL);
      display.drawRect(sx(1 + i * BUTTON_STEP), sy(BAR_Y), BUTTON_W / 4, BUTTON_H / 4, HINT);
    }
  } else if (which == Layout::Overlay) {
    const uint16_t glass = display.alphaBlend(120, TFT_BLACK, artColor);
    for (int slot = 0; slot < 4; slot++) {
      display.fillRect(sx(overlaySlotX(g, slot)), sy(g.artY + OV_MARGIN), OV_BUTTON_W / 4, OV_BUTTON_H / 4, glass);
    }
    display.fillCircle(sx(g.artX + OV_BIG_INSET), sy(g.countY), OV_BIG_R / 4, glass);
    display.fillCircle(sx(g.artX + g.artW - OV_BIG_INSET), sy(g.countY), OV_BIG_R / 4, glass);
    display.fillRoundRect(sx(g.artX + (g.artW - OV_CHIP_W) / 2), sy(g.groupY - OV_CHIP_H / 2), OV_CHIP_W / 4,
                          OV_CHIP_H / 4, 2, glass);
  }
}

