// A small card in the current tone: the token's frame, art and a plate with its name.
void drawTonePreview(int x, int y) {
  const Token token = currentToken();
  const int artX = x + SET_PREVIEW_PAD;
  const int artY = y + SET_PREVIEW_PAD;
  const int plateY = artY + SET_PREVIEW_ART_H + 3;

  display.fillRoundRect(x, y, SET_PREVIEW_W, SET_PREVIEW_H, 5, TFT_BLACK);
  display.fillRoundRect(x + 1, y + 1, SET_PREVIEW_W - 2, SET_PREVIEW_H - 2, 4, frameColor(styleOf(token)));
  if (!drawArtThumb(artX, artY, SET_PREVIEW_ART_W, SET_PREVIEW_ART_H, true)) {
    // Without art, a gray ramp shows the curve.
    for (int i = 0; i < SET_PREVIEW_ART_W; i++) {
      const uint16_t v = i * 31 / (SET_PREVIEW_ART_W - 1);
      display.drawFastVLine(artX + i, artY, SET_PREVIEW_ART_H, toneColor((v << 11) | (v << 6) | v));
    }
  }
  display.fillRoundRect(artX, plateY, SET_PREVIEW_ART_W, SET_PREVIEW_PLATE_H, 3, plateColor);
  String name = token.name;
  while (name.length() > 1 && display.textWidth(name, 1) > SET_PREVIEW_ART_W - 10) name.remove(name.length() - 1);
  display.setTextDatum(ML_DATUM);
  display.setTextColor(CARD_INK, plateColor);
  display.drawString(name, artX + 5, plateY + SET_PREVIEW_PLATE_H / 2, 1);
}

